let mobile=matchMedia('(max-width:760px)').matches,W=1,H=1,dpr=1,frame=0,raf=0,last=0,phase=0,enabled=root.dataset.motion!=='off'&&!reduce.matches;
let mouse={x:.55,y:.45,tx:.55,ty:.45},bursts=[],stars=[],points=[],edges=[];
const TAU=Math.PI*2,pink=[255,104,177],cyan=[110,239,237],violet=[166,120,255];
function rgba(c,a){return `rgba(${c[0]},${c[1]},${c[2]},${a})`}
function rand(seed){let n=seed;return()=>{n=(n*1664525+1013904223)>>>0;return n/4294967296}}
