function resize(){mobile=matchMedia('(max-width:760px)').matches;W=canvas.clientWidth||innerWidth;H=canvas.clientHeight||innerHeight;dpr=Math.min(devicePixelRatio||1,mobile?1:1.4);canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);build();if(!enabled)draw(0);else start()}
function rot(p,ax,ay,az){let [x,y,z]=p,ca=Math.cos(ax),sa=Math.sin(ax),cb=Math.cos(ay),sb=Math.sin(ay),cc=Math.cos(az),sc=Math.sin(az);let yy=y*ca-z*sa,zz=y*sa+z*ca,xx=x*cb+zz*sb;z=-x*sb+zz*cb;x=xx*cc-yy*sc;y=xx*sc+yy*cc;return [x,y,z]}
function project(p,cx,cy,size){const s=3.8/(3.8+p[2]);return [cx+p[0]*size*s,cy+p[1]*size*s,p[2],s]}
function halo(x,y,r,color,opacity){const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,rgba(color,opacity));g.addColorStop(.36,rgba(color,opacity*.4));g.addColorStop(1,rgba(color,0));ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2)}
